from PySide6.QtWidgets import QCheckBox,QComboBox,QFormLayout,QLabel,QLineEdit,QVBoxLayout,QWizardPage
from ...enums import RoadArrangement
from ..widgets import HelpPanel
class ArrangementPage(QWizardPage):
    def __init__(self):
        super().__init__(); self.setTitle("Road arrangement and project"); self.arrangement=QComboBox(); self.arrangement.addItem("Select…",None); self.arrangement.addItem("Single carriageway",RoadArrangement.SINGLE_CARRIAGEWAY); self.arrangement.addItem("One carriageway of a divided road",RoadArrangement.DIVIDED_CARRIAGEWAY_ONE_SIDE); self.arrangement.addItem("Mixed/asymmetric road",RoadArrangement.MIXED_OR_ASYMMETRIC); self.median=QCheckBox("A physical median or kerbed island separates directions"); self.error=QLabel(); self.error.setStyleSheet("color:#b00020"); self.project=QLineEdit(); self.road=QLineEdit(); self.section=QLineEdit(); self.notes=QLineEdit(); layout=QVBoxLayout(self); form=QFormLayout(); form.addRow("Arrangement",self.arrangement); form.addRow("Physical division",self.median); form.addRow("Project",self.project); form.addRow("Road name",self.road); form.addRow("Section reference",self.section); form.addRow("Notes",self.notes); layout.addLayout(form); layout.addWidget(self.error); layout.addWidget(HelpPanel("Painted lines, painted medians and flush chevron areas do not create divided carriageways. A physical median or kerbed island does. When divided, calculate one carriageway at a time.")); self.arrangement.currentIndexChanged.connect(self._changed); self.median.toggled.connect(self._changed)
    def _changed(self):self.error.setText("Select one carriageway of a divided road." if self.median.isChecked() and self.arrangement.currentData()!=RoadArrangement.DIVIDED_CARRIAGEWAY_ONE_SIDE else ""); self.completeChanged.emit()
    def isComplete(self):return self.arrangement.currentData() is not None and not self.error.text()
